            # Global cross-reference summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_cross_reference_summary(
                method, environ, start_response
            )

        if path == "/cross-reference-usage":
            # Per-repository cross-reference usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_usage(
                method, environ, start_response
            )

        if path == "/cross-reference-targets":
            # Per-resolved-local-target cross-reference usage view; the
            # handler answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_targets(
                method, environ, start_response
            )

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/advisories":
            return _handle_advisories(method, environ, start_response)

        if path == "/graph":
            return _handle_graph(method, environ, start_response)

        if path == "/graph/stats":
            return _handle_graph_stats(method, environ, start_response)

        if path == "/dependency-closure-summary":
            # Per-resource dependency closure size summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_closure_summary(
                method, environ, start_response
            )

        if path == "/dependency-usage":
            # Per-depended-upon-resource dependents usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_usage(method, environ, start_response)

        if path == "/digest-usage":
            # Global resource usage view grouped by registration digest;
            # the handler answers the 405 (Allow: GET) for every other
